(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Tệp của bạn, chính xác đến từng byte.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Đã sao chép.</span>","hero.cycle":"Đã sao chép.|Đã di chuyển.|Đã đồng bộ.|Đã xác minh.","hero.sub":"Một trình sao chép tệp cho máy tính chạy Windows, macOS và Linux, có xác minh bằng tổng kiểm, tiếp tục sau sự cố, đồng bộ hai chiều, hoàn tác và máy chủ tệp riêng. Không tài khoản, không đo lường từ xa và không AI.","hero.chipLanguages":"18 ngôn ngữ","hero.chipCli":"Dòng lệnh","what.title":"Đây là gì","what.p1":"Sao chép một thư mục lớn bằng hộp thoại sao chép có sẵn của hệ thống cho bạn biết rất ít: không có tổng kiểm, không được quyết định chuyện gì xảy ra với những tệp đã tồn tại, và không có đường lui khi mất điện giữa chừng.","what.p2":"Freally File Manager là một trình sao chép được làm ra để bạn yên tâm giao phó việc đó. Thả tệp vào cửa sổ của nó, chọn đích, và nó sao chép chúng qua đường sao chép nhanh nhất của hệ thống. Bật xác minh lên, nó sẽ đọc lại từng bản sao và đối chiếu với tổng kiểm của bản gốc.","what.p3":"Xung quanh trình sao chép là mọi thứ bạn cần đến sau đó: lịch sử của mọi tác vụ kèm chạy lại và hoàn tác, công cụ tổng kiểm, đồng bộ hai chiều và phản chiếu trực tiếp, ảnh chụp nhanh, một máy chủ tệp tích hợp và dòng lệnh cho các script.","features.title":"Bên trong có gì","features.copy.title":"Bản sao chính xác từng byte","features.copy.body":"Mọi tệp được sao chép từng byte một qua các đường nhanh có sẵn của hệ thống, và được nhân bản tức thì trên những ổ đĩa hỗ trợ. Tạm dừng, tiếp tục hoặc hủy bất kỳ tác vụ nào, và quyết định trước khi bắt đầu chuyện gì xảy ra khi một tệp đã tồn tại.","features.verify.title":"Xác minh khi bạn yêu cầu","features.verify.body":"Bật xác minh, và mỗi bản sao được đọc lại rồi đối chiếu với bản gốc bằng một trong tám loại tổng kiểm, từ CRC32 và xxHash3 đến SHA-256 và BLAKE3. Sai khác luôn được báo ra, không bao giờ bị che giấu.","features.resume.title":"Vượt qua cả mất điện","features.resume.body":"Một nhật ký ghi lại mỗi bản sao đã đi được bao xa. Sau sự cố hoặc khởi động lại, phần đã ghi được kiểm tra và quá trình sao chép tiếp tục từ đó thay vì bắt đầu lại từ đầu.","features.sync.title":"Đồng bộ hai chiều","features.sync.body":"Giữ hai thư mục khớp nhau theo cả hai chiều, hoặc phản chiếu thư mục này sang thư mục kia. Một tệp bị thay đổi ở cả hai phía là một xung đột: cả hai phiên bản đều được giữ lại và bạn là người chọn.","features.history.title":"Lịch sử và hoàn tác","features.history.body":"Mọi tác vụ đều được ghi lại. Chạy lại nó, chỉ thử lại những tệp thất bại, hoặc hoàn tác lần sao chép hay di chuyển gần nhất: các bản sao bị hoàn tác đi vào Thùng rác, không bao giờ bị xóa thẳng.","features.checks.title":"Kiểm tra tệp bất cứ lúc nào","features.checks.body":"Tính mã băm của bất kỳ tệp nào bằng tám loại tổng kiểm, tạo và kiểm tra tệp .sha256 hoặc .sfv, so sánh một thư mục với bản sao của nó sau nhiều tháng, và xuất một báo cáo có chữ ký về những gì đã được sao chép.","features.server.title":"Máy chủ tệp của riêng bạn","features.server.body":"Chia sẻ một thư mục cho các máy tính khác qua WebDAV, HTTP thuần, API tương thích S3 hoặc SFTP, chỉ đọc nếu bạn muốn, được bảo vệ bằng mật khẩu hoặc token.","features.free.title":"Miễn phí, riêng tư, không AI","features.free.body":"Không tài khoản, không đo lường từ xa và không học máy. Tệp của bạn chỉ đi đến nơi bạn gửi chúng, và việc kiểm tra cập nhật hằng ngày có thể tắt được.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng, cũ nhất trước. Tất cả đều đã xong: đã dựng, đã kiểm thử và đã gắn thẻ.","ladder.rung.v0.19.84":"Bản phát hành đầu tiên: bản sao chính xác từng byte với xác minh tùy chọn, tiếp tục sau sự cố, lịch sử, đồng bộ hai chiều và phản chiếu trực tiếp, máy chủ tệp và dòng lệnh, bằng 18 ngôn ngữ.","ladder.rung.v0.19.85":"Thư viện: các ảnh chụp nhanh đã khử trùng lặp mà bạn có thể sao lưu, so sánh và khôi phục, cùng các kho lưu trữ bạn có thể nhập từ restic, Borg và Kopia hoặc xuất sang chúng.","ladder.rung.v0.20.0":"Lưới an toàn: hoàn tác lần sao chép hoặc di chuyển gần nhất, xóa vào Thùng rác, chỉ thử lại những tệp thất bại, tệp tổng kiểm, và tháo ổ đĩa khi một tác vụ hoàn tất.","ladder.rung.v0.22.0":"Băm, báo cáo và lập lịch: trình kiểm tra mã băm, báo cáo sao chép có chữ ký, xác minh lại, cứu dữ liệu từ phương tiện bị hỏng, lịch trình, mục ưa thích, chế độ di động và trợ năng.","ladder.rung.v1.0.0":"Bản phát hành về độ chính xác: rà soát toàn bộ mã nguồn, từng phần một, cùng mọi bản sửa lỗi rút ra từ đó.","ladder.note":"Một phiên bản đã xong là đã được dựng và gắn thẻ. Không phiên bản nào là bản tải xuống trên trang này: ở đây chưa có bản tải xuống nào.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.verify.title":"Xác minh tắt cho đến khi bạn bật lên","honest.verify.body":"Kiểm tra một bản sao nghĩa là đọc nó thêm một lần nữa, nên đây là một tùy chọn chứ không phải mặc định. Chọn một loại tổng kiểm trong Cài đặt → Chuyển, và mọi bản sao sau đó đều được kiểm tra.","honest.notYet.title":"Hai điều 1.0 chưa làm được","honest.notYet.body":"Nó không thể hủy tệp một cách an toàn, và không thể sao chép lên lưu trữ đám mây. Phần Cài đặt đã có chỗ cho cả hai, nhưng chưa cái nào được kết nối trong phiên bản 1.0.0.","honest.network.title":"Khi nào nó kết nối mạng","honest.network.body":"Sao chép giữa các ổ đĩa của chính bạn, xác minh và xóa không gửi yêu cầu mạng nào. Nó kết nối mạng cho những gì bạn thiết lập, như máy chủ tệp hoặc kiểm tra một tài khoản đám mây, và để kiểm tra cập nhật khi khởi động, tối đa một lần mỗi ngày, điều bạn có thể tắt trong Cài đặt → Cập nhật.","honest.downloads.title":"Ở đây chưa có bản tải xuống nào","honest.downloads.body":"Không có trình cài đặt, không có bản dựng xem trước và không có liên kết tải xuống trên trang web này. Khi điều đó thay đổi, trang này sẽ nói rõ.","site.tagline":"Sao chép, di chuyển, đồng bộ và xác minh tệp của bạn, chính xác đến từng byte.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Các tệp bạn sao chép, đồng bộ và chia sẻ vẫn là của bạn. Tác giả của Freally File Manager không nhận bất kỳ quyền sở hữu nào đối với chúng.","featuresPage.lead":"Một trình sao chép tệp chính xác từng byte với xác minh, tiếp tục sau sự cố, đồng bộ, hoàn tác và máy chủ tệp riêng, cùng bản ghi của mọi tác vụ nó từng chạy.","featuresPage.version":"Trang này mô tả Freally File Manager phiên bản 1.0.0, phiên bản hiện tại: mọi thứ trên trang đều có trong 1.0.0.","featuresPage.numbers.intro":"Mỗi con số được đếm từ chính mã nguồn của phiên bản 1.0.0. Không có gì được làm tròn lên.","featuresPage.numbers.hashes":"loại tổng kiểm để xác minh bản sao","featuresPage.numbers.collisions":"lựa chọn cho một tệp đã tồn tại","featuresPage.numbers.sidecars":"định dạng tệp tổng kiểm mà nó ghi và kiểm tra","featuresPage.numbers.server":"cách chia sẻ một thư mục: WebDAV, HTTP, S3 và SFTP","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Mọi thứ Freally File Manager làm được hiện nay đều miễn phí cho tất cả mọi người: không có gói trả phí, không thuê bao, không khóa giấy phép và không tài khoản.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.copy.title":"Bộ máy sao chép","featuresPage.cards.copy.body":"Bản sao chính xác từng byte qua đường nhanh nhất của mỗi hệ thống, với nhân bản tức thì trên các hệ thống tệp hỗ trợ. Những thư mục khổng lồ được xử lý theo luồng mà không làm đầy bộ nhớ, và bạn chọn trước khi sao chép chuyện gì xảy ra với các tệp đã tồn tại: giữ cả hai, bỏ qua, ghi đè, ghi đè nếu mới hơn, chỉ ghi đè nếu khác, hoặc hỏi.","featuresPage.cards.verify.title":"Xác minh sau khi sao chép","featuresPage.cards.verify.body":"Tám loại tổng kiểm: CRC32, MD5, SHA-1, SHA-256, SHA-512, xxHash3-64, xxHash3-128 và BLAKE3. Mỗi bản sao được đọc lại và so với bản gốc, và nếu có sai khác thì tệp bị đánh dấu thất bại thay vì lọt qua mà không ai hay.","featuresPage.cards.checks.title":"Băm, xác minh lại và tệp tổng kiểm","featuresPage.cards.checks.body":"Bảng “Băm” kiểm tra tệp với một tổng kiểm bạn dán vào. “Xác minh lại” so sánh một thư mục với bản sao của nó sau nhiều tháng mà không ghi một byte nào. Tạo tệp .md5, .sha1, .sha256, .sha512, .b3 hoặc .sfv cho cả một thư mục, và thả một tệp như vậy vào cửa sổ để kiểm tra.","featuresPage.cards.resume.title":"Tiếp tục sau sự cố và khởi động lại","featuresPage.cards.resume.body":"Một nhật ký ghi lại tiến độ của từng bản sao. Ở lần khởi chạy tiếp theo, phần đã ghi được đối chiếu với mã băm của nó, và quá trình sao chép tiếp tục từ đó.","featuresPage.cards.history.title":"Lịch sử, chạy lại và hoàn tác","featuresPage.cards.history.body":"Mọi tác vụ đều được ghi lại. Chạy lại bất kỳ tác vụ nào, chỉ thử lại những tệp thất bại, xuất một báo cáo có chữ ký, hoặc hoàn tác lần sao chép hay di chuyển gần nhất: các bản sao bị hoàn tác đi vào Thùng rác, không bao giờ bị xóa thẳng.","featuresPage.cards.sync.title":"Đồng bộ và phản chiếu trực tiếp","featuresPage.cards.sync.body":"Đồng bộ hai chiều, phản chiếu theo chiều nào cũng được, hoặc chỉ đóng góp, với xung đột được giữ thành hai tệp để bạn chọn. Phản chiếu trực tiếp theo dõi một thư mục và đồng bộ mọi thay đổi bạn lưu.","featuresPage.cards.server.title":"Máy chủ tệp tích hợp","featuresPage.cards.server.body":"Chia sẻ bất kỳ thư mục nào qua WebDAV, HTTP, API tương thích S3 hoặc SFTP, từ Cài đặt hoặc bằng lệnh freally serve, chỉ đọc nếu bạn muốn, được bảo vệ bằng token hoặc mật khẩu, kèm một endpoint số liệu Prometheus.","featuresPage.cards.library.title":"Ảnh chụp nhanh và sao lưu","featuresPage.cards.library.body":"Một kho lưu trữ khử trùng lặp lưu mỗi phiên bản của một tệp đúng một lần. Duyệt dòng thời gian, khôi phục bất kỳ ảnh chụp nhanh nào, sao lưu các thư mục đã chọn theo yêu cầu, và nhập kho lưu trữ từ restic, Borg hoặc Kopia.","featuresPage.cards.salvage.title":"Cứu dữ liệu từ ổ đĩa sắp hỏng","featuresPage.cards.salvage.body":"“Cứu dữ liệu” sao chép mọi thứ còn đọc được của một tệp trên ổ đĩa sắp hỏng, điền số không vào những chỗ không đọc được để phần còn lại giữ đúng vị trí, lưu một bản đồ các khoảng trống, và ở lần chạy sau chỉ thử lại những khoảng trống đó.","featuresPage.cards.metadata.title":"Không gì bị mất một cách âm thầm","featuresPage.cards.metadata.body":"Tệp thưa vẫn giữ nguyên là tệp thưa, còn luồng dữ liệu thay thế, thuộc tính mở rộng và dấu “tải xuống từ Internet” đi theo từng tệp. Một tệp đang bị chương trình khác khóa trên Windows có thể được sao chép từ một ảnh chụp nhanh.","featuresPage.cards.desktop.title":"Một phần của máy tính của bạn","featuresPage.cards.desktop.body":"Sao chép và di chuyển từ menu chuột phải trong Explorer, Finder, Nautilus, Dolphin và Thunar, dán qua ứng dụng từ bất cứ đâu bằng Ctrl+Shift+V, và lên lịch cho các tác vụ đã lưu trong bộ lập lịch có sẵn của hệ thống.","featuresPage.cards.cli.title":"Dòng lệnh cho script","featuresPage.cards.cli.body":"Lệnh freally sao chép, di chuyển và xác minh, lập kế hoạch cho một tác vụ trước khi chạy, chia sẻ thư mục và nhập bản sao lưu, đồng thời báo cáo theo từng dòng JSON với các mã thoát được ghi trong tài liệu.","featuresPage.compare.title":"Đặt cạnh các công cụ thương mại","featuresPage.compare.intro":"Freally File Manager 1.0.0 đặt cạnh sáu công cụ thương mại mà người ta mua để sao chép, kiểm tra, đồng bộ và quản lý tệp. Mọi ô của sản phẩm khác đều lấy từ chính các trang của nhà sản xuất, được kiểm tra vào ngày 2 tháng 10 năm 2026, và giá là giá niêm yết tại Mỹ tính đến tháng 10 năm 2026.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.freeToday":"Hiện miễn phí","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.note.aud":"bán bằng đô la Úc","featuresPage.compare.note.eur":"bán bằng euro","featuresPage.compare.note.updatesYear":"một năm cập nhật","featuresPage.compare.note.perYear":"mỗi năm, tối đa năm thiết bị","featuresPage.compare.row.verify":"Kiểm tra từng bản sao với một tổng kiểm","featuresPage.compare.legend.yes":"có","featuresPage.compare.note.optional":"tùy chọn, tám loại tổng kiểm","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.note.checksumTool":"một công cụ tổng kiểm, không chạy sau mỗi lần sao chép","featuresPage.compare.row.systems":"Windows, macOS và Linux","featuresPage.compare.note.oldMac":"ứng dụng Mac cũ hơn","featuresPage.compare.note.webLinux":"Linux: chỉ có giao diện web","featuresPage.compare.row.resume":"Tiếp tục sao chép sau sự cố hoặc khởi động lại","featuresPage.compare.note.afterStop":"sau khi dừng, bằng cách mở lại danh sách","featuresPage.compare.note.ftpOnly":"chỉ FTP","featuresPage.compare.note.ftpDownloads":"chỉ tải xuống qua FTP","featuresPage.compare.note.connectOnly":"chỉ truyền qua GoodSync Connect","featuresPage.compare.row.sync":"Đồng bộ hai chiều giữ lại cả hai phía của xung đột","featuresPage.compare.note.byDate":"hai chiều, theo ngày","featuresPage.compare.note.noConflicts":"hai chiều; xung đột không được ghi trong tài liệu","featuresPage.compare.note.newerWins":"tệp mới hơn thắng","featuresPage.compare.row.server":"Chia sẻ một thư mục qua WebDAV, S3 hoặc SFTP","featuresPage.compare.note.ownProtocol":"chỉ với các ứng dụng GoodSync khác","featuresPage.compare.row.undo":"Hoàn tác một lần sao chép hoặc di chuyển đã xong","featuresPage.compare.note.keepsVersions":"giữ lại các tệp bị thay thế","featuresPage.compare.row.salvage":"Cứu những gì còn đọc được từ ổ đĩa sắp hỏng","featuresPage.compare.row.report":"Xuất báo cáo tổng kiểm của từng tệp","featuresPage.compare.note.signable":"có thể ký","featuresPage.compare.note.logNoSums":"nhật ký không có tổng kiểm","featuresPage.compare.note.logView":"một màn hình xem nhật ký","featuresPage.compare.note.compareReport":"một báo cáo so sánh riêng","featuresPage.compare.note.changeReport":"nhật ký và một báo cáo thay đổi","featuresPage.compare.legend.no":"không","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Tóm lại: chỉ Freally File Manager có tất cả. Không công cụ nào trong sáu công cụ liệt kê trên chính trang của nhà sản xuất một máy chủ WebDAV, S3 hay SFTP, hay một cách cứu tệp từ ổ đĩa sắp hỏng, và trong sáu công cụ chỉ GoodSync ghi trong tài liệu việc phát hiện xung đột đồng bộ.","featuresPage.compare.theyWinTitle":"Chỗ họ hơn","featuresPage.compare.theyWin":"Chỗ họ hơn: Directory Opus, Total Commander và ForkLift cho phép bạn duyệt và sắp xếp mọi thư mục trong cửa sổ riêng của chúng, còn Freally File Manager 1.0.0 làm việc với những tệp bạn đưa cho nó. TeraCopy và Directory Opus có thể xóa tệp một cách an toàn, và ForkLift, Beyond Compare và GoodSync sao chép lên lưu trữ đám mây; Freally File Manager 1.0.0 không làm được điều nào trong hai điều đó. TeraCopy cũng có nhiều loại tổng kiểm hơn: 17 so với tám.","featuresPage.compare.asOf":"Cột của Freally File Manager là phiên bản 1.0.0, và giá của nó là giá hôm nay: hiện nó miễn phí, và các phiên bản sau này có thể được bán. Các sản phẩm khác cũng thay đổi; bảng này phản ánh tình hình tại ngày 2 tháng 10 năm 2026.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.exact.title":"Đúng từng byte, hoặc là thất bại","featuresPage.why.exact.body":"Một bản sao có đúng những byte như bản gốc, hoặc nó bị báo là thất bại. Và một tệp thay đổi trong lúc đang được đọc sẽ bị đánh dấu, được sao chép lại hoặc bị đánh thất bại, tùy bạn chọn, thay vì được coi là một bản sao sạch.","featuresPage.why.native.title":"Đường nhanh có sẵn của hệ thống","featuresPage.why.native.body":"Nó yêu cầu Windows, macOS và Linux sao chép từng tệp theo cách nhanh nhất mà chúng biết, và nhân bản tệp tức thì ở nơi hệ thống tệp cho phép, thay vì đẩy từng byte qua một vòng lặp của riêng nó.","featuresPage.why.safe.title":"Không có gì phá hủy do vô tình","featuresPage.why.safe.body":"Khi di chuyển, bản gốc chỉ bị xóa sau khi sao chép thành công, hoàn tác đưa tệp vào Thùng rác thay vì xóa chúng, và hoàn tác không bao giờ động đến một tệp đã thay đổi kể từ khi được sao chép.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không đo lường từ xa và không tài khoản. Tệp của bạn chỉ đi đến nơi bạn gửi chúng, và đo lường từ xa thậm chí không thể bật lên bằng cách sửa tệp cài đặt.","featuresPage.why.noAi.title":"Không AI","featuresPage.why.noAi.body":"Mọi quyết định của nó đến từ mã thông thường, có thể đoán trước: tổng kiểm, kích thước và dấu thời gian. Bên trong không có thư viện học máy nào.","featuresPage.limits.heading":"Những giới hạn, nói thẳng","featuresPage.limits.intro":"Một danh sách tính năng giấu đi những thiếu sót của nó thì không đáng đọc. Mọi thứ ở trên đều có trong phiên bản 1.0.0, và đây là những gì nó không làm.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.verify":"Nó không xác minh bản sao cho đến khi bạn bật xác minh trong Cài đặt → Chuyển.","featuresPage.limits.queue":"Không thể sắp xếp lại thứ tự các tác vụ trong hàng đợi: mỗi tác vụ bắt đầu ngay khi được thêm vào.","featuresPage.limits.portable":"Chế độ di động giữ cài đặt và hồ sơ bên cạnh ứng dụng, nhưng lịch sử, nhật ký tiếp tục và mật khẩu đám mây đã lưu vẫn nằm trên máy tính mà nó đang chạy.","featuresPage.limits.shred":"Nó không thể hủy tệp một cách an toàn: Cài đặt → Xóa an toàn có ở đó, nhưng không có gì trong 1.0.0 xóa qua nó.","featuresPage.limits.cloud":"Nó không thể sao chép lên lưu trữ đám mây: bạn có thể thêm và kiểm tra tài khoản đám mây trong Cài đặt → Backend từ xa, nhưng chưa có bản sao nào được gửi đến đó.","featuresPage.limits.downloads":"Trang web này chưa có bản tải xuống nào, và trang này cũng không có.","docs.intro":"Cách sử dụng Freally File Manager phiên bản 1.0.0. Nút, thẻ và menu được gọi ở đây đúng như tên mà ứng dụng đặt cho chúng.","docs.start.title":"Bắt đầu","docs.copy.title":"Sao chép tệp","docs.move.title":"Di chuyển tệp","docs.verify.title":"Xác minh một bản sao","docs.history.title":"Lịch sử, chạy lại và hoàn tác","docs.checks.title":"Băm, xác minh lại và tệp tổng kiểm","docs.sync.title":"Đồng bộ hai thư mục","docs.filters.title":"Chọn những gì được sao chép","docs.shell.title":"Menu chuột phải và phím tắt dán","docs.library.title":"Ảnh chụp nhanh và sao lưu","docs.salvage.title":"Cứu một tệp từ ổ đĩa sắp hỏng","docs.server.title":"Chạy nó như một máy chủ tệp","docs.migrate.title":"Nhập kho lưu trữ restic, Borg hoặc Kopia","docs.settings.title":"Cài đặt","docs.shortcuts.title":"Phím tắt","featuresPage.speed.title":"Nó nhanh đến đâu","docs.trouble.title":"Mẹo và khắc phục sự cố","docs.report.title":"Báo cáo sự cố","docs.privacy.title":"Quyền riêng tư và mạng","docs.start.p1":"Freally File Manager là ứng dụng máy tính cho Windows 11, macOS 12 trở lên, và Linux. Lần đầu mở, nó hiện thỏa thuận cấp phép: cuộn đến cuối, rồi chọn “Tôi đồng ý” để bắt đầu, hoặc “Từ chối & Thoát”.","docs.start.p2":"Cửa sổ là một vùng thả nằm phía trên bảng “Hoạt động”. “Thêm tệp”, “Thêm thư mục” và “Nhập danh sách” nằm ở thanh trên cùng. Thanh dưới cùng chứa “Tổng cộng”, “Lịch sử”, “Băm”, “Xác minh lại”, “Cứu dữ liệu”, “Đồng bộ”, “Thư viện”, “Tác vụ” và biểu tượng bánh răng để mở Cài đặt.","docs.start.p3":"Trang web này chưa có bản tải xuống nào.","docs.copy.s1":"Kéo tệp hoặc thư mục vào cửa sổ, hoặc nhấp “Thêm tệp” hay “Thêm thư mục” ở thanh trên cùng.","docs.copy.s2":"Hộp thoại “Chuyển các mục đã thả” mở ra. Để “Thao tác” ở “Sao chép” và nhấp “Chọn đích” để chọn thư mục sẽ sao chép vào.","docs.copy.s3":"Trong “Nếu tệp đã tồn tại”, chọn chuyện gì xảy ra với những tệp đã có sẵn ở đó: giữ cả hai, bỏ qua, ghi đè, chỉ ghi đè nếu mới hơn, chỉ ghi đè nếu nội dung khác, bỏ qua nếu giống hệt và hỏi trong trường hợp còn lại, hoặc hỏi mỗi lần.","docs.copy.s4":"Dùng “Thứ tự” để sắp xếp danh sách theo tên hoặc kích thước, hoặc kéo các hàng. Tệp luôn đứng trước thư mục.","docs.copy.s5":"Nhấp “Bắt đầu sao chép”. Mỗi tệp có một hàng trong bảng “Hoạt động” với tiến độ, tốc độ và thời gian còn lại, và thanh trên cùng hiển thị tổng số.","docs.copy.p1":"Để tạm dừng một tác vụ, chọn hàng của nó và nhấn phím cách, hoặc nhấp chuột phải vào nó và chọn “Tạm dừng”; “Tiếp tục” chạy tiếp và “Hủy” dừng hẳn. “Tạm dừng mọi tác vụ”, “Tiếp tục mọi tác vụ” và “Hủy mọi tác vụ” nằm ở thanh trên cùng.","docs.copy.p2":"Nếu đích không đủ chỗ cho tất cả, bạn sẽ được cảnh báo trước khi byte đầu tiên được chuyển và có thể chọn những mục cần sao chép. Hộp thoại cũng đánh dấu những tên mà đích không thể chứa, như tên dành riêng, ký tự không được phép và đường dẫn quá dài, và đề nghị đổi tên chúng.","docs.copy.p3":"Dùng “Khi hoàn tất” ở cuối cửa sổ để đóng ứng dụng, đăng xuất, tắt máy hoặc cho máy ngủ khi mọi tác vụ đã xong.","docs.move.p1":"Di chuyển hoạt động giống như sao chép: trong hộp thoại “Chuyển các mục đã thả”, đặt “Thao tác” thành “Di chuyển”, chọn đích và nhấp “Bắt đầu di chuyển”.","docs.move.p2":"Mỗi tệp được sao chép trước, và bản gốc chỉ bị xóa sau khi sao chép thành công. Nếu có gì thất bại, bản gốc vẫn ở nguyên chỗ cũ và hàng đó được đánh dấu là thất bại.","docs.move.p3":"Để mọi lần di chuyển đều có thể khôi phục, bật “Gửi tệp nguồn đã di chuyển vào thùng rác” trong Cài đặt → Xóa an toàn: khi đó bản gốc sẽ vào Thùng rác thay vì bị xóa.","docs.verify.p1":"Xác minh tắt cho đến khi bạn bật lên. Mở Cài đặt → Chuyển và chọn một loại tổng kiểm trong “Xác minh sau khi sao chép”: xxHash3 nhanh nhất, BLAKE3 mạnh mà vẫn nhanh, còn SHA-256 khớp với hầu hết các công cụ khác.","docs.verify.p2":"Từ đó trở đi, mọi bản sao đều được kiểm tra. Bản gốc được băm trong lúc đọc, nên không phải đọc hai lần; khi bản sao đã được ghi xong, bản sao cũng được băm và hai mã băm được so sánh.","docs.verify.p3":"Nếu khớp, hàng đó hoàn tất ở trạng thái xong. Nếu sai khác, hàng đó thất bại và hiển thị tổng kiểm mong đợi lẫn tổng kiểm thực tế. Nếu một bản sao lớn có vẻ đứng yên ở 100%, có lẽ thanh trên cùng đang hiện “Đang xác minh”: việc kiểm tra vẫn đang chạy.","docs.history.p1":"Nhấp “Lịch sử” ở thanh dưới cùng. Mọi tác vụ được liệt kê kèm loại, nguồn, đích, kích thước, trạng thái và thời lượng, và bạn có thể lọc danh sách theo loại, trạng thái hoặc văn bản. “Xuất CSV” lưu danh sách đó.","docs.history.p2":"Từ một tác vụ, bạn có thể “Chạy lại” nó, dùng “Thử lại thất bại” để chỉ sao chép những tệp thất bại, “Xuất thất bại” để lưu danh sách đó, “Xác minh lại” nó, hoặc xuất một “Chứng nhận”: một báo cáo HTML, CSV hoặc JSON có thể in, ghi tổng kiểm, kích thước và trạng thái của từng tệp, mà bạn có thể ký bằng khóa của riêng mình.","docs.history.p3":"“Hoàn tác”, hoặc Ctrl+Z, đảo ngược lần sao chép hoặc di chuyển gần nhất sau khi cho thấy chính xác những gì sẽ bị động đến. Tệp đã sao chép đi vào Thùng rác, và chỉ khi chúng vẫn khớp với những gì đã được sao chép; tệp đã di chuyển trở về nơi chúng đến.","docs.history.p4":"“Tổng cộng”, cũng ở thanh dưới cùng, hiển thị số liệu tích lũy về byte, tệp và tác vụ, cùng biểu đồ 30 ngày gần nhất.","docs.checks.p1":"“Băm” ở thanh dưới cùng mở trình kiểm tra mã băm. Thêm tệp hoặc thư mục, chọn một thuật toán và nhấp “Tính mã băm”. Dán một tổng kiểm, một dòng từ tệp tổng kiểm hoặc một hàng SFV để so sánh, hoặc chọn hai tệp để xem chúng có giống hệt nhau không.","docs.checks.p2":"“Xác minh lại”, cũng ở thanh dưới cùng, so sánh lại một thư mục với bản sao của nó, bất cứ lúc nào và không ghi gì cả. Nó báo cáo từng tệp khớp, khác, thiếu trong bản sao, chỉ có trong bản sao, hoặc không thể đọc.","docs.checks.p3":"Để tạo tệp tổng kiểm cho cả một thư mục, nhấp chuột phải vào một tác vụ đã xong và chọn “Tạo tổng kiểm (SHA-256)”. Để kiểm tra một tệp như vậy, thả tệp .md5, .sha1, .sha256, .sha512, .b3 hoặc .sfv vào cửa sổ: mọi tệp được liệt kê trong đó sẽ được băm và kết quả được hiển thị.","docs.sync.s1":"Nhấp “Đồng bộ” ở thanh dưới cùng, rồi nhấp “Thêm cặp”.","docs.sync.s2":"Đặt nhãn cho cặp, chọn thư mục bên trái và bên phải, rồi chọn một chế độ: “Hai chiều”; “Phản chiếu”, từ trái sang phải hoặc từ phải sang trái; hoặc “Đóng góp”, sao chép từ trái sang phải và không bao giờ xóa.","docs.sync.s3":"Nhấp “Lưu cặp”, rồi nhấp “Chạy ngay”.","docs.sync.p1":"Khi một tệp đã thay đổi ở cả hai phía kể từ lần chạy trước, không có gì bị ghi đè: phiên bản kia được giữ bên cạnh dưới dạng tệp xung đột đồng bộ, và “Xem xung đột” cho phép bạn giữ bên trái, bên phải hoặc cả hai.","docs.sync.p2":"“Bắt đầu phản chiếu trực tiếp” theo dõi thư mục bên trái và đồng bộ lại sau mỗi thay đổi bạn lưu. Cặp hiển thị “Đang theo dõi” trong khi chạy; “Dừng phản chiếu trực tiếp” kết thúc nó.","docs.filters.p1":"Cài đặt → Bộ lọc áp dụng cho mọi lần sao chép: các mẫu để bao gồm hoặc loại trừ, như **/*.log hoặc **/node_modules, giới hạn kích thước và ngày, và có bỏ qua tệp ẩn, tệp hệ thống hoặc tệp chỉ đọc hay không. Một thư mục khớp với mẫu loại trừ sẽ bị bỏ qua toàn bộ.","docs.filters.p2":"Để sao chép một danh sách tệp chính xác, nhấp “Nhập danh sách” ở thanh trên cùng và chọn một tệp TXT, CSV hoặc JSON chứa các đường dẫn. Sao chép chúng phẳng vào một thư mục, hoặc giữ cấu trúc thư mục của chúng bên dưới một gốc chung.","docs.filters.p3":"Trước một lần sao chép lớn, “Xuất kế hoạch” trong hộp thoại “Chuyển các mục đã thả” lưu một báo cáo về những gì lần sao chép sẽ thêm, thay thế, bỏ qua hoặc gặp xung đột, trước khi một byte nào được chuyển đi.","docs.shell.p1":"Freally File Manager có thể thêm “Copy with Freally File Manager” và “Move with Freally File Manager” vào menu chuột phải: trong Explorer trên Windows, trong Finder trên macOS, và trong Nautilus, Dolphin và Thunar trên Linux. Trên Windows, Cài đặt → Shell bật hoặc tắt chúng.","docs.shell.p2":"Sao chép tệp như bình thường bằng Ctrl+C (Cmd+C trên Mac), rồi nhấn Ctrl+Shift+V (Cmd+Shift+V trên Mac) ở bất cứ đâu: các tệp sẽ mở trong hộp thoại của Freally File Manager. Đổi phím tắt hoặc tắt nó trong Cài đặt → Chung.","docs.shell.p3":"Trên Windows, bạn có thể đi xa hơn: “Chặn trình xử lý sao chép mặc định”, trong Cài đặt → Shell, chuyển chính thao tác sao chép và dán của Explorer qua Freally File Manager, và mỗi lần dán sau đó sẽ hỏi bạn muốn một bản sao thông thường của hệ thống hay một bản sao được xác minh. “Khôi phục trình xử lý sao chép của Windows” hoàn tác điều này chỉ với một cú nhấp.","docs.library.p1":"“Thư viện” ở thanh dưới cùng mở kho lưu trữ: nội dung của mỗi tệp được lưu một lần, theo các khối đã khử trùng lặp, và mọi ảnh chụp nhanh được hiển thị trên một dòng thời gian. Thanh trên cùng cho thấy dung lượng thực sự chiếm trên đĩa so với lượng dữ liệu mà nó đại diện.","docs.library.p2":"Trong “Nguồn”, thêm một thư mục và nhấp “Sao lưu ngay” để tạo một ảnh chụp nhanh; lần sao lưu thứ hai của một thư mục không thay đổi gần như không tốn chỗ. Mỗi nguồn có thể giữ mọi ảnh chụp nhanh của nó, vài cái gần nhất, hoặc một tập luân phiên, và có thể chạy hằng giờ, hằng ngày hoặc hằng tuần.","docs.library.p3":"Trong “Ảnh chụp”, “Khôi phục” cho phép bạn duyệt các tệp của một ảnh chụp nhanh, chọn đích và quyết định chuyện gì xảy ra với những tệp đã tồn tại. “Quên” bỏ một ảnh chụp nhanh, và “Thu hồi dung lượng” giải phóng những khối không còn gì sử dụng.","docs.salvage.p1":"“Cứu dữ liệu” ở thanh dưới cùng sao chép mọi thứ còn đọc được của một tệp trên ổ đĩa bị hỏng. Chọn tệp, rồi chọn nơi ghi bản sao.","docs.salvage.p2":"Những chỗ không đọc được sẽ được thử lại theo các mảnh ngày càng nhỏ, rồi được điền số không để phần còn lại của tệp giữ đúng vị trí, và một bản đồ các khoảng trống được lưu bên cạnh bản sao. Chạy lại “Cứu dữ liệu” trên cùng tệp đó sau này và chỉ những khoảng trống được thử lại.","docs.salvage.p3":"Một tệp được cứu mà còn khoảng trống thì không phải là bản sao chính xác từng byte, và mục lịch sử của nó ghi rõ điều đó.","docs.server.p1":"Freally File Manager có thể chia sẻ một thư mục cho các máy tính khác qua WebDAV, HTTP thuần, API tương thích S3 hoặc SFTP.","docs.server.s1":"Mở Cài đặt → Máy chủ và đánh dấu các giao thức muốn cung cấp.","docs.server.s2":"Đặt địa chỉ lắng nghe (bind). Mặc định, 127.0.0.1:8080, chỉ phục vụ máy tính này; 0.0.0.0:8080 hoặc địa chỉ mạng của bạn phục vụ cả các máy khác, khi tường lửa của bạn cho phép.","docs.server.s3":"Chọn thư mục được chia sẻ, đánh dấu “Chỉ đọc” nếu không được tải lên hay xóa gì, và chọn cách xác thực: không có, bearer token, hoặc tên người dùng và mật khẩu.","docs.server.s4":"Nhấp “Khởi động máy chủ”. Dòng trạng thái hiển thị địa chỉ, và một liên kết “Số liệu” trỏ đến endpoint Prometheus. “Dừng máy chủ”, hoặc thoát ứng dụng, sẽ dừng nó.","docs.server.protocol":"Giao thức","docs.server.connect":"Kết nối bằng","docs.server.webdav":"“Ánh xạ ổ đĩa mạng” trong Windows, “Kết nối với máy chủ” trong Finder, GNOME Files hoặc davfs2","docs.server.http":"Trình duyệt web, curl hoặc wget","docs.server.s3client":"Dòng lệnh AWS, rclone hoặc bất kỳ thư viện S3 nào, với tên người dùng và mật khẩu làm khóa truy cập và khóa bí mật","docs.server.sftp":"sftp, scp, FileZilla, WinSCP hoặc rclone","docs.server.p2":"WebDAV và HTTP có thể chạy cùng nhau trên một địa chỉ; S3 và SFTP mỗi cái cần một máy chủ riêng, và S3 cần mật khẩu hoặc không xác thực, chứ không dùng token.","docs.server.p3":"Một máy chủ mở ra mạng mà không có xác thực thì bất cứ thứ gì truy cập được nó đều có thể đọc, và cả ghi nếu nó không ở chế độ chỉ đọc. Ngoài phạm vi máy tính của chính bạn, hãy luôn đặt token hoặc mật khẩu.","docs.server.p4":"Trên một máy tính không có màn hình, lệnh freally làm được điều tương tự:","docs.migrate.p1":"Lệnh freally migrate đọc kho lưu trữ của một công cụ sao lưu khác, dựng lại từng tệp và lưu nó vào một kho lưu trữ theo định dạng mở CDR-0, được khử trùng lặp lại bằng cách chia khối riêng của Freally File Manager.","docs.migrate.p2":"Mỗi trình nhập đều được kiểm thử để khôi phục mọi tệp chính xác từng byte. Định dạng CDR-0 được mô tả trong bản đặc tả công bố cùng với trang web này.","docs.migrate.spec":"Đọc bản đặc tả CDR-0","docs.settings.p1":"Biểu tượng bánh răng ở thanh dưới cùng mở Cài đặt. Thay đổi có hiệu lực ngay, không cần khởi động lại. Những thẻ bạn sẽ dùng nhiều nhất:","docs.settings.general":"Chung: ngôn ngữ, giao diện của ứng dụng, khởi động khi đăng nhập, thu nhỏ xuống khay hệ thống, cách hiển thị lỗi, phím tắt dán và theo dõi bộ nhớ tạm.","docs.settings.transfer":"Chuyển: xác minh, kích thước bộ đệm, số tệp được sao chép cùng lúc, nhân bản, dấu thời gian và quyền, tệp thưa, tệp bị khóa và các dấu bảo mật mà một tệp mang theo.","docs.settings.filters":"Bộ lọc: những gì cần bao gồm và loại trừ.","docs.settings.shell":"Shell: menu chuột phải và việc tiếp quản thao tác sao chép của chính Windows.","docs.settings.network":"Mạng: giới hạn tốc độ, cố định hoặc theo lịch.","docs.settings.server":"Máy chủ: máy chủ tệp tích hợp.","docs.settings.updates":"Cập nhật: kiểm tra cập nhật hằng ngày, và một nút để kiểm tra ngay.","docs.settings.profiles":"Hồ sơ: lưu cài đặt của bạn dưới một cái tên, chuyển đổi giữa chúng, và nhập hoặc xuất chúng.","docs.shortcuts.keys":"Phím","docs.shortcuts.action":"Chức năng","docs.shortcuts.paste":"Dán các tệp đã sao chép qua Freally File Manager, từ bất cứ đâu","docs.shortcuts.undo":"Hoàn tác lần sao chép hoặc di chuyển gần nhất","docs.shortcuts.pause":"Tạm dừng hoặc tiếp tục tác vụ đang được chọn","docs.shortcuts.escape":"Đóng hộp thoại hoặc ngăn kéo trên cùng","featuresPage.speed.intro":"Đo vào ngày 30 tháng 4 năm 2026 trên một máy tính xách tay Windows 11 (Intel Core i9-13900HX, 32 GB bộ nhớ, ổ NVMe PCIe 4.0), sao chép bên trong cùng một ổ NTFS. Mỗi con số là trung vị của nhiều lần chạy, tính bằng MiB mỗi giây: cao hơn là nhanh hơn.","featuresPage.speed.workload":"Nội dung được sao chép","featuresPage.speed.cmd":"Lệnh copy của Windows","featuresPage.speed.mixed":"Một thư mục gồm 100 tệp, từ 100 KB đến 150 MB","featuresPage.speed.file512":"Một tệp 512 MB","featuresPage.speed.file256":"Một tệp 256 MB","featuresPage.speed.file10g":"Một tệp 10 GB","featuresPage.speed.result":"Nó nhanh nhất với thư mục nhiều tệp và với tệp 512 MB, và chậm hơn một chút so với Robocopy và lệnh copy của Windows với các tệp 256 MB và 10 GB. Nó nhanh hơn FastCopy và TeraCopy trong mọi bài thử.","featuresPage.speed.caveat":"Một máy và một ổ đĩa, đo bằng một bản dựng có trước 1.0.0, và mỗi công cụ được chạy từ dòng lệnh riêng của nó, tính cả thời gian khởi động. Con số của bạn sẽ khác, và khi ổ đích là khâu chậm nhất thì mọi công cụ đều chạy theo tốc độ của nó.","docs.trouble.slow.title":"Vì sao sao chép chậm?","docs.trouble.slow.body":"Khi một lần sao chép chạy dưới tốc độ lẽ ra phải đạt, thanh trên cùng hiển thị một huy hiệu nhỏ nêu nguyên nhân: ổ nguồn, ổ đích, mạng, phần mềm diệt vi-rút, bộ xử lý hoặc nhiệt độ. Di chuột lên huy hiệu để xem chi tiết.","docs.trouble.stall.title":"Sao chép dừng ở 100%","docs.trouble.stall.body":"Nếu thanh trên cùng hiện “Đang xác minh”, bản sao đang được đối chiếu với tổng kiểm của nó. Điều đó là bình thường với tệp lớn; hãy tắt xác minh trong Cài đặt → Chuyển nếu bạn không cần.","docs.trouble.locked.title":"Một tệp đang được dùng trên Windows","docs.trouble.locked.body":"Tệp được mở theo cách để các chương trình khác vẫn dùng được, và một tệp bị từ chối sẽ được thử lại vài lần. Nếu một chương trình khác vẫn giữ độc quyền tệp đó, hãy đóng chương trình đó, hoặc chọn trong Cài đặt → Chuyển để sao chép tệp bị khóa từ một ảnh chụp nhanh.","docs.trouble.permission.title":"Bị từ chối quyền truy cập","docs.trouble.permission.body":"Khi tệp bị từ chối vì quyền, Freally File Manager có thể thử lại chúng qua một lời nhắc quản trị viên duy nhất cho cả danh sách, và hiển thị chính xác những tệp nó sẽ động đến trước khi bạn chấp thuận.","docs.trouble.changed.title":"Nguồn thay đổi trong khi sao chép","docs.trouble.changed.body":"Tệp đã thay đổi trong lúc đang được đọc, nên bản sao có thể trộn lẫn nội dung cũ và mới. Theo mặc định tệp được đánh dấu; thay vào đó, Cài đặt → Chuyển có thể sao chép lại nó một lần hoặc đánh thất bại.","docs.report.p1":"Khi chính ứng dụng gây ra lỗi, một nút “Báo cáo” xuất hiện bên cạnh thông báo. Sau một sự cố, lần khởi chạy tiếp theo sẽ đề nghị “Báo cáo” hoặc “Bỏ qua”.","docs.report.p2":"“Báo cáo” mở trang này trong trình duyệt của bạn, với các thông tin kỹ thuật đã được điền sẵn: bạn có thể đọc nhưng không thể thay đổi chúng. Thêm điều bạn đang làm và, nếu muốn, một địa chỉ email để nhận phản hồi.","docs.report.p3":"Không có gì được gửi trừ khi bạn nhấn “Gửi” trên trang đó, và không bao giờ có gì được gửi ngầm. Đường dẫn tệp trong báo cáo được rút gọn, với thư mục chính của bạn hiển thị là ~.","docs.privacy.p1":"Freally File Manager không có tài khoản và không có đo lường từ xa. Công tắc đo lường từ xa trong cài đặt của nó bị tắt vĩnh viễn: một giá trị được ghi tay vào tệp cài đặt sẽ bị bỏ qua.","docs.privacy.p2":"Sao chép, di chuyển và xác minh tệp trên các ổ đĩa của chính bạn không gửi yêu cầu mạng nào. Ứng dụng kết nối mạng cho những gì bạn thiết lập, như máy chủ tệp hoặc kiểm tra một tài khoản đám mây, và để kiểm tra cập nhật khi khởi động, tối đa một lần mỗi ngày. Việc kiểm tra cập nhật chỉ đọc danh sách các bản phát hành, không gửi tệp hay đường dẫn nào của bạn, và có thể tắt trong Cài đặt → Cập nhật.","docs.privacy.p3":"Nó không chứa AI: mọi quyết định của nó đến từ tổng kiểm, kích thước và dấu thời gian, và không có thư viện học máy nào là một phần của nó.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.done":"v1.0.0 đã xong","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally File Manager hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Tám ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally File Manager, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v1.0.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally File Manager, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.086fc6b9eb45":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-08-22\">2026-08-22</time></span><span class=\"release__title\">Bản phát hành về độ chính xác</span>","changelog.490081990d07":"Mọi tính năng từ 0.22.0 đều có ở đây. Điều thay đổi là một đợt rà soát toàn bộ mã nguồn, từng phần một, cùng những bản sửa lỗi rút ra từ đó. Một vài lỗi trong số đó có thể làm mất dữ liệu mà không hề hiện ra thông báo lỗi nào.","changelog.1246fc93bca0":"Đã sửa","changelog.f485232d66fe":"<strong>Thư mục lối tắt.</strong> Sao chép một thư mục mà bản thân nó là lối tắt (liên kết tượng trưng hoặc junction) không sao chép gì mà vẫn báo thành công, và trong đồng bộ, cùng lỗi đó có thể làm trống phía bên kia. Giờ thư mục như vậy bị từ chối, kèm lý do.","changelog.b5ca80d81af1":"<strong>Hủy.</strong> Hủy một lần sao chép thư mục lớn có thể bị treo thay vì dừng lại. Giờ một lần sao chép có thể được hủy ở bất kỳ thời điểm nào.","changelog.02ca0292cb02":"<strong>Máy chủ S3.</strong> Các tệp được tải lên bằng dòng lệnh AWS hoặc một thư viện AWS bị lưu ở trạng thái hỏng, và các lần tải lên lớn hơn khoảng 8 MB thất bại hoàn toàn. Giờ cả hai đều đến nơi chính xác từng byte, và một lần tải lên bị cắt ngang sẽ bị từ chối thay vì được lưu.","changelog.00349386830d":"<strong>Cơ sở dữ liệu đồng bộ.</strong> Một cặp đồng bộ có cơ sở dữ liệu nằm bên trong một trong các thư mục của chính nó đã coi cơ sở dữ liệu đó là một tệp cần đồng bộ, và có thể xóa nó giữa lúc đang chạy.","changelog.f1d849633a99":"<strong>SFTP.</strong> Các backend từ xa SFTP không bao giờ kết nối được: mọi lần kiểm tra kết nối đều thất bại, bất kể cài đặt ra sao. Giờ chúng đã kết nối được.","changelog.fd3bac863255":"<strong>Mã hóa.</strong> Mã hóa có thể quay sang ghi tệp không mã hóa khi không chuẩn bị được khóa của nó. Giờ nó dừng tác vụ thay vì làm vậy.","changelog.94d9edfe63bf":"<strong>Máy chủ chỉ đọc.</strong> Một loại yêu cầu vẫn có thể ghi vào máy chủ được đặt ở chế độ chỉ đọc. Giờ không loại nào làm được nữa.","changelog.44b306c0f111":"<strong>Tiến độ.</strong> Một lần quét được tiếp tục đã báo sai số lượng tệp, nên thanh tiến độ sai theo cả hai hướng.","changelog.e19d94517f4b":"<strong>Đăng nhập đám mây.</strong> Đăng nhập vào một tài khoản đám mây có thể thất bại mà không rõ lý do, và mỗi lần bỏ dở đăng nhập lại làm rò rỉ một luồng.","changelog.b4dfc2b6c682":"<strong>Máy chủ đã biết.</strong> Một máy chủ SFTP được ghim trong tệp <code>known_hosts</code> bị từ chối mỗi khi nó đưa ra bất kỳ loại khóa nào ngoài loại đầu tiên trong danh sách, tức là hầu hết thời gian.","changelog.042c3c3e6ae5":"<strong>Thông báo.</strong> Thông báo ntfy đến dưới dạng mã thô thay vì nội dung tin nhắn.","changelog.6e72325e73e3":"<strong>Hộp thoại.</strong> Escape đóng nhầm hộp thoại khi có hai hộp thoại đang mở, và một vài bảng Cài đặt bị bố trí sai.","changelog.acdd2a3d27ea":"<strong>Lời nhắc quản trị viên (bảo mật).</strong> Trên Linux và macOS, một chương trình khác chạy dưới tài khoản của bạn có thể tráo kết nối của chính nó vào trong lúc lời nhắc mật khẩu đang mở, và trở thành bên chạy với quyền quản trị viên khi bạn chấp thuận. Lời nhắc giờ không thể bị chiếm quyền theo cách đó nữa.","changelog.577866d56150":"<strong>Chữ hoa.</strong> Trên Windows và macOS, <code>Photo.jpg</code> và <code>photo.jpg</code> là một tệp, nhưng đồng bộ đã coi chúng là hai, sao chép tệp này đè lên tệp kia, rồi có thể xóa tệp còn lại. Giờ chúng lại là một tệp.","changelog.f029d4f5e78c":"<strong>Ổ đĩa mạng.</strong> Khi chia sẻ một thư mục nằm trên ổ đĩa mạng, một phản hồi chậm không còn làm nghẽn mọi yêu cầu khác.","changelog.0ab356a87732":"<strong>Trình trợ giúp.</strong> Các bộ cài đặt đã thiếu trình trợ giúp nhỏ đảm nhận mọi việc cần quyền quản trị viên, nên trên bản đã cài, những thao tác đó thất bại, chẳng hạn thử lại một lần sao chép bị từ chối vì quyền hoặc thay đổi menu chuột phải. Giờ trình trợ giúp được phát hành kèm ứng dụng.","changelog.87a38eb16185":"<strong>Kiểm tra cập nhật.</strong> Nó thất bại mọi lần, trên mọi hệ thống. Giờ nó đọc danh sách cập nhật được công bố cùng mỗi bản phát hành.","changelog.7a7604d1c245":"<strong>Ghi chú phát hành.</strong> Ngăn “Cập nhật” lặp lại liên kết nhật ký thay đổi bốn lần và hiển thị nó như văn bản chết. Giờ ghi chú chỉ xuất hiện một lần, với một liên kết mở trong trình duyệt của bạn.","changelog.9b82b2eda918":"<strong>Tài liệu</strong> hứa hẹn những hành vi mà mã nguồn không có đã được sửa lại.","changelog.d04ef101813e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">Băm, báo cáo, lập lịch và tính di động</span>","changelog.6b02e0d363a4":"Đã thêm","changelog.68724824e3df":"<strong>Trình kiểm tra mã băm.</strong> Băm bất kỳ tệp hoặc thư mục nào bằng bất kỳ thuật toán nào trong tám thuật toán, dán một tổng kiểm để so sánh, hoặc so sánh hai tệp. Trên Windows, nó cũng có trong menu chuột phải.","changelog.c3b19859a18b":"<strong>Báo cáo sao chép.</strong> Xuất bất kỳ tác vụ đã xong nào thành báo cáo HTML có thể in, CSV hoặc JSON, ghi tổng kiểm, kích thước và trạng thái của từng tệp, và ký bằng khóa của riêng bạn nếu muốn, để bất kỳ ai cũng có thể kiểm tra mà không cần Freally File Manager.","changelog.19be8c01d283":"<strong>Xác minh lại.</strong> So sánh lại một thư mục với bản sao của nó, nhiều tháng sau, mà không ghi một byte nào: cái gì khớp, cái gì khác, cái gì bị thiếu và cái gì được thêm vào.","changelog.66e001519d0e":"<strong>Bác sĩ tên tệp.</strong> Trước khi sao chép, tìm những tên mà đích không thể chứa, như tên dành riêng, ký tự không được phép, dấu chấm và khoảng trắng ở cuối, đường dẫn quá dài và những tên chỉ khác nhau ở chữ hoa chữ thường, rồi đổi tên chúng.","changelog.497980a00899":"<strong>Sao chép từ danh sách.</strong> Nhập một danh sách đường dẫn từ tệp TXT, CSV hoặc JSON làm các tệp cần sao chép, phẳng hoặc giữ nguyên thư mục của chúng.","changelog.e70e0cbe1516":"<strong>Báo cáo kế hoạch.</strong> Xuất những gì một lần sao chép sẽ thêm, thay thế, bỏ qua hoặc gặp xung đột, trước khi một byte nào được chuyển đi.","changelog.650a70fbc1fb":"<strong>Cứu dữ liệu.</strong> Sao chép những gì còn đọc được của một tệp trên ổ đĩa sắp hỏng, điền số không vào những chỗ không đọc được, lưu một bản đồ các khoảng trống, và sau này chỉ thử lại các khoảng trống.","changelog.098ec7cfa416":"<strong>Một lời nhắc cho nhiều tệp.</strong> Khi nhiều tệp bị từ chối vì quyền, chấp thuận một danh sách và thử lại tất cả qua một lời nhắc quản trị viên duy nhất.","changelog.f231630df24f":"<strong>Lịch trình.</strong> Tạo, sửa và xóa các mục trong bộ lập lịch có sẵn của hệ thống (Bộ lập lịch tác vụ, launchd hoặc systemd), có hiển thị thời gian chạy kế tiếp và không cần quyền quản trị viên.","changelog.9d433f36b4af":"<strong>Hàng đợi ổ đĩa.</strong> Sửa việc nhận diện ổ đĩa khi nó sai: cho các thư mục dùng chung một hàng đợi, hoặc tách chúng ra, với số worker riêng cho từng hàng đợi.","changelog.1be51474008d":"<strong>Ưu tiên.</strong> Tạm dừng các tác vụ khác đang chạy trong khi một tác vụ hoàn tất, rồi tiếp tục đúng những tác vụ đó.","changelog.60c6175a344d":"<strong>Ưa thích.</strong> Đánh dấu nguồn, đích và các cặp nguồn–đích, và giữ một cặp gần đây làm mục ưa thích chỉ với một cú nhấp.","changelog.332cc7aa8523":"<strong>Chế độ di động.</strong> <code>--portable</code>, hoặc một tệp đánh dấu bên cạnh ứng dụng, giữ cài đặt và hồ sơ bên cạnh nó. Lịch sử, nhật ký tiếp tục và mật khẩu đám mây đã lưu vẫn nằm trên máy tính, và Cài đặt có ghi rõ điều đó.","changelog.2eb9e1222a1d":"<strong>Trợ năng.</strong> Escape đóng hộp thoại trên cùng từ bất cứ đâu, chế độ giảm chuyển động được tôn trọng ở mọi nơi, tiêu điểm luôn hiển thị, và trình đọc màn hình đọc được số tác vụ đang chạy, đã xong và thất bại.","changelog.3c3c4afca24f":"<strong>Bảo vệ khi nguồn thay đổi.</strong> Một tệp thay đổi trong lúc đang được sao chép sẽ bị đánh dấu, được sao chép lại một lần, hoặc bị đánh thất bại, tùy bạn chọn.","changelog.1d54a1bf0dc3":"<strong>Khởi động khi đăng nhập.</strong> Khởi động thu nhỏ xuống khay hệ thống, để menu chuột phải, phím tắt dán và lịch trình hoạt động ngay từ lúc bạn đăng nhập.","changelog.8dbeb02b73fb":"<strong>Cài đặt có thể làm mất dữ liệu của bạn.</strong> Lưu Cài đặt đã đặt lại về mặc định các đích được ghim trên khay, kho lưu trữ, tài khoản đám mây, cặp đồng bộ và nhiều thứ khác. Giờ mọi nhóm đều được giữ nguyên sau khi lưu, và có một bài kiểm thử đảm bảo điều đó.","changelog.3e59c181d02c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-20\">2026-07-20</time></span><span class=\"release__title\">Lưới an toàn</span>","changelog.245019914a17":"<strong>Hoàn tác.</strong> Ctrl+Z, hoặc “Hoàn tác” trên một hàng lịch sử, cho thấy việc đảo ngược lần sao chép hoặc di chuyển gần nhất sẽ động đến những gì, rồi thực hiện nó. Tệp đã sao chép đi vào Thùng rác, và chỉ khi chúng vẫn khớp với những gì đã được sao chép.","changelog.6632a5f505b6":"<strong>Xóa vào Thùng rác</strong>, và một tùy chọn để đưa bản gốc của tệp đã di chuyển vào đó thay vì xóa nó.","changelog.8242fb20ac7f":"<strong>Thử lại thất bại.</strong> Chỉ sao chép lại những tệp thất bại trong một tác vụ, hoặc xuất danh sách của chúng.","changelog.6b92af518239":"<strong>Hai lựa chọn mới cho tệp đã tồn tại.</strong> Chỉ ghi đè nếu nội dung khác, hoặc bỏ qua nếu giống hệt và hỏi trong trường hợp còn lại.","changelog.dca682f75970":"<strong>Tháo ổ đĩa.</strong> Tháo an toàn ổ đĩa mà một tác vụ đã ghi vào.","changelog.e2eb082a0eff":"<strong>Không ngủ khi đang sao chép.</strong> Máy tính luôn thức khi có bất kỳ tác vụ nào đang chạy.","changelog.d2392c075c64":"<strong>Tệp tổng kiểm.</strong> Tạo tệp <code>.md5</code>, <code>.sha1</code>, <code>.sha256</code>, <code>.sha512</code>, <code>.b3</code> hoặc <code>.sfv</code> cho cả một thư mục, và thả một tệp như vậy vào cửa sổ để kiểm tra mọi tệp được liệt kê trong đó.","changelog.95c1ab071772":"<strong>Tiếp quản thao tác sao chép của Windows.</strong> Tùy chọn chuyển chính thao tác sao chép và dán của Explorer qua Freally File Manager, với cách quay lại chỉ bằng một cú nhấp. Mỗi lần dán đều đề nghị một bản sao thông thường của hệ thống hoặc một bản sao được xác minh.","changelog.a20adfb45e43":"<strong>Thỏa thuận cấp phép.</strong> Nó được hiển thị khi ứng dụng mở lần đầu.","changelog.be1a948a30a9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.85</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span><span class=\"release__title\">Thư viện và công cụ sao lưu</span>","changelog.d28e3ce211c4":"<strong>Thư viện.</strong> Một dòng thời gian của mọi ảnh chụp nhanh, cho thấy dung lượng được lưu so với lượng dữ liệu mà nó đại diện: sao lưu các thư mục đã chọn, và khôi phục bất kỳ ảnh chụp nhanh nào đến nơi bạn chọn.","changelog.eeb0847e8169":"<strong>Lưu trữ nén và thu gọn.</strong> Ảnh chụp nhanh có thể được nén, và việc bảo trì thu hồi và thu gọn dung lượng không còn gì sử dụng, với mọi tác vụ dài được hiển thị trong “Tác vụ”.","changelog.c73e54bfcf32":"<strong>So sánh và báo cáo.</strong> So sánh hai ảnh chụp nhanh, và xem thống kê cùng biểu đồ của kho lưu trữ.","changelog.f9c43f8de8b1":"<strong>Khóa kho lưu trữ.</strong> Nhiều mật khẩu cho một kho lưu trữ, và một khóa khôi phục.","changelog.905de5db76c9":"<strong>Nhân bản.</strong> Sao chép một kho lưu trữ sang nơi thứ hai, chỉ gửi những gì phía bên kia còn thiếu.","changelog.ed05f802fa45":"<strong>Công cụ sao lưu khác.</strong> Nhập một kho lưu trữ restic, Borg hoặc Kopia bằng <code>freally migrate</code>, và ghi ngược ra một kho bằng <code>freally export</code>.","changelog.9310ff4d82b1":"Mười lăm vấn đề được tìm thấy trong một đợt rà soát toàn bộ, bao gồm những cách mà một bản sao lưu có thể mất dữ liệu mà không báo gì.","changelog.9124de6aa268":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-27\">2026-06-27</time></span><span class=\"release__title\">Bản phát hành đầu tiên</span>","changelog.facf44888f54":"<strong>Sao chép và di chuyển chính xác từng byte</strong> qua đường nhanh nhất của mỗi hệ thống, với nhân bản tức thì trên các hệ thống tệp hỗ trợ, và thư mục cỡ nào cũng được xử lý theo luồng mà không làm đầy bộ nhớ.","changelog.36feaab53bd3":"<strong>Xác minh sau khi sao chép</strong> với tám loại tổng kiểm, từ CRC32 và xxHash3 đến SHA-256 và BLAKE3.","changelog.d269986b29b2":"<strong>Tạm dừng, tiếp tục và hủy</strong> bất kỳ tác vụ nào, chọn chuyện gì xảy ra với tệp đã tồn tại, và thử lại với quyền quản trị viên một tệp bị từ chối vì quyền.","changelog.294162447b0a":"<strong>Tiếp tục sau sự cố hoặc khởi động lại</strong> nhờ một nhật ký ghi tiến độ của từng bản sao.","changelog.59d391bd4f36":"<strong>Lịch sử và tổng cộng</strong>: mọi tác vụ được ghi lại, lọc, xuất ra CSV và chạy lại chỉ với một cú nhấp.","changelog.bcb57f6f639f":"<strong>Bộ lọc</strong>: mẫu bao gồm và loại trừ, kích thước, ngày và thuộc tính tệp.","changelog.e262b2471351":"<strong>Đồng bộ hai chiều</strong> có phát hiện xung đột, các chế độ phản chiếu và đóng góp, và phản chiếu trực tiếp đồng bộ mọi thay đổi đã lưu.","changelog.f299d8319e86":"<strong>Giới hạn tốc độ</strong>, cố định hoặc theo lịch.","changelog.7ba87a11a88a":"<strong>Không gì bị mất một cách âm thầm</strong>: tệp thưa, luồng dữ liệu thay thế, thuộc tính mở rộng và dấu “tải xuống từ Internet” đều được giữ lại, và một tệp bị khóa trên Windows có thể được sao chép từ một ảnh chụp nhanh.","changelog.a0a934ff3831":"<strong>Máy tính của bạn</strong>: menu chuột phải trên Windows, macOS và Linux, phím tắt dán hoạt động từ bất cứ đâu, và một biểu tượng trên khay hệ thống.","changelog.2180818af954":"<strong>Máy chủ tệp</strong> qua WebDAV, HTTP, API tương thích S3 hoặc SFTP, với <code>freally serve</code> cho máy tính không có màn hình.","changelog.d49f07823c77":"<strong>Dòng lệnh <code>freally</code></strong>, với đầu ra theo từng dòng JSON, mã thoát được ghi trong tài liệu, và các tác vụ bạn có thể lập kế hoạch trước khi chạy.","changelog.e50cd2fc0077":"<strong>Vì sao chậm?</strong> Một huy hiệu nêu ra thứ đang kìm hãm lần sao chép.","changelog.3d3204d8e967":"<strong>18 ngôn ngữ</strong>, tiếng Ả Rập từ phải sang trái."};
